# -*- coding: utf-8 -*-
# PickTV / PeekPro 小说源 - 小说聚合搜索
# 在搜索框输入书名，一次并发搜索全部子源并合并结果。
# 结果 vod_id 带「源key::」前缀，详情/正文会自动路由回对应源。
import os
import sys
import json
import types
import threading
import importlib.util
from concurrent.futures import ThreadPoolExecutor

from base.spider import Spider

# 参与聚合的子源（文件名 -> 路由 key），按推荐顺序排列
SUB_SOURCES = [
    ("燃文小说.py", "燃文小说"),
    ("笔趣阁.py", "笔趣阁"),
    ("灯笔小说.py", "灯笔小说"),
    ("顶点小说.py", "顶点小说"),
    ("七猫小说.py", "七猫小说"),
]

# 章节 URL 特征 -> 路由 key（用于 playerContent）
_URL_ROUTES = [
    ("qimao://", "七猫小说"),
    ("wxsy.net", "顶点小说"),
    ("dengbi.net", "灯笔小说"),
    ("ranwen.la", "燃文小说"),
    ("biquwu.cc", "笔趣阁"),
    ("fsshu.com", "笔趣阁"),
]


class Spider(Spider):
    def getName(self):
        return "小说聚合搜索"

    def getDependence(self):
        # 关键：告诉 app 需要一起下载的子源文件名（不带 .py，Java 侧会补 .py）
        # 否则 app 缓存里没有这些文件，聚合源会加载 0 个子源，首页/搜索全空。
        return [fname[:-3] for fname, _ in SUB_SOURCES]

    def init(self, extend=""):
        self.sources = {}  # key -> 子源实例
        self._lock = threading.Lock()
        here = self._module_dir()
        for fname, key in SUB_SOURCES:
            sp = self._load_source(here, fname, key)
            if sp is not None:
                self.sources[key] = sp
        print(f"[聚合搜索] 已加载 {len(self.sources)}/{len(SUB_SOURCES)} 个子源: {list(self.sources.keys())}")

    # ---------------- 加载子源 ----------------
    def _module_dir(self):
        try:
            return os.path.dirname(os.path.abspath(__file__))
        except Exception:
            pass
        # 兜底：从 sys.path 找 py 目录
        for p in sys.path:
            if p and os.path.isdir(p) and os.path.exists(os.path.join(p, "燃文小说.py")):
                return p
        # 常见兜底：PickTV/FongMi 的 py 缓存目录
        for base in (os.getcwd(), r"py", os.path.join(os.getcwd(), "py")):
            if os.path.isfile(os.path.join(base, "燃文小说.py")):
                return os.path.abspath(base)
        return os.getcwd()

    def _load_source(self, here, fname, key):
        # 三级兜底：磁盘文件 -> 内嵌副本 -> sys.modules/import
        # 1) 磁盘文件：getDependence 已下载 / 本地测试时 py/ 就在旁边
        path = os.path.join(here, fname)
        if os.path.isfile(path) and os.path.getsize(path) > 100:
            try:
                return self._spawn("agg_" + key, path, fname)
            except Exception as e:
                print(f"[聚合搜索] 文件加载 {fname} 失败: {e}")
        # 2) 内嵌副本：app 没下载子源文件（api 非 URL 时 getDependence 无法解析）也能用
        code = _EMBEDDED.get(key)
        if code:
            try:
                return self._spawn_code("agg_" + key, code, fname)
            except Exception as e:
                print(f"[聚合搜索] 内嵌加载 {fname} 失败: {e}")
        # 3) 已加载过的模块（单独源也配置了同名文件时）
        try:
            mod = importlib.import_module(fname[:-3])
            sp = mod.Spider()
            sp.init()
            return sp
        except Exception as e:
            print(f"[聚合搜索] import 加载 {fname} 失败: {e}")
        return None

    def _spawn(self, name, path, fname):
        spec = importlib.util.spec_from_file_location(name, path)
        mod = importlib.util.module_from_spec(spec)
        sys.modules[name] = mod
        spec.loader.exec_module(mod)
        sp = mod.Spider()
        sp.init()
        return sp

    def _spawn_code(self, name, code, fname):
        mod = types.ModuleType(name)
        mod.__file__ = "<%s>" % fname
        sys.modules[name] = mod
        exec(compile(code, mod.__file__, "exec"), mod.__dict__)
        sp = mod.Spider()
        sp.init()
        return sp

    # ---------------- 首页 / 分类 ----------------
    def homeContent(self, filter=False):
        return {"class": [{"type_id": "all", "type_name": "综合"}]}

    def _tag(self, book, name):
        book["vod_id"] = f"{name}::{book.get('vod_id', '')}"
        book["vod_remarks"] = name
        return book

    def homeVideoContent(self):
        videos, seen = [], set()

        def collect(name, sp):
            try:
                r = sp.homeVideoContent() or {}
            except Exception:
                r = {}
            for b in (r.get("list") or []):
                with self._lock:
                    b = self._tag(b, name)
                    k = (b.get("vod_name", ""), b.get("vod_author", ""))
                    if k not in seen:
                        seen.add(k)
                        videos.append(b)

        self._run_parallel(collect)
        return {"list": videos[:60]}

    def categoryContent(self, tid, pg, filter=False, extend=""):
        if tid != "all":
            return {"list": []}
        return self.homeVideoContent()

    # ---------------- 聚合搜索 ----------------
    def searchContent(self, key, quick=False, pg="1"):
        try:
            if int(pg or 1) > 1:
                return {"list": [], "page": 1, "pagecount": 1, "limit": 20, "total": 0}
        except Exception:
            pass
        if not self.sources:
            return {"list": []}
        results, seen = [], set()

        def do(name, sp):
            try:
                r = sp.searchContent(key, quick, "1") or {}
            except Exception as e:
                print(f"[聚合搜索] {name} 搜索异常: {e}")
                r = {}
            for b in (r.get("list") or []):
                b = self._tag(b, name)
                k = (str(b.get("vod_name", "")).strip(), str(b.get("vod_author", "")).strip())
                with self._lock:
                    if k not in seen:
                        seen.add(k)
                        results.append(b)

        self._run_parallel(do)
        return {"list": results, "page": 1, "pagecount": 1, "limit": 20, "total": len(results)}

    def _run_parallel(self, fn, timeout=15):
        if not self.sources:
            return
        try:
            ex = ThreadPoolExecutor(max_workers=len(self.sources))
        except Exception as e:
            print(f"[聚合搜索] 线程池不可用，改为顺序执行: {e}")
            for name, sp in self.sources.items():
                try:
                    fn(name, sp)
                except Exception:
                    pass
            return
        try:
            futs = {ex.submit(fn, name, sp): name for name, sp in self.sources.items()}
            for fut in futs:
                try:
                    fut.result(timeout=timeout)
                except Exception:
                    pass
        except Exception as e:
            # 线程池提交/等待整体失败：退化为顺序执行，保证结果可用
            print(f"[聚合搜索] 并发异常，改为顺序执行: {e}")
            for name, sp in self.sources.items():
                try:
                    fn(name, sp)
                except Exception:
                    pass
        finally:
            # 不等待仍在跑的超时任务，避免拖住整个源
            try:
                ex.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass

    # ---------------- 路由 ----------------
    def _split(self, rid):
        rid = str(rid)
        if "::" in rid:
            name, _, orig = rid.partition("::")
            if name in self.sources:
                return name, orig
        return "", rid

    def _route(self, url):
        name, _ = self._split(url)
        if name:
            return name
        u = str(url)
        for pat, key in _URL_ROUTES:
            if pat in u:
                return key
        return ""

    # ---------------- 详情 / 正文 ----------------
    def detailContent(self, ids):
        ids = ids if isinstance(ids, list) else [ids]
        name, orig = self._split(ids[0])
        sp = self.sources.get(name)
        if not sp:
            return {}
        try:
            r = sp.detailContent([orig]) or {}
        except Exception as e:
            print(f"[聚合搜索] {name} 详情异常: {e}")
            return {}
        for b in (r.get("list") or []):
            self._tag(b, name)
        return r

    def playerContent(self, flag, id, vipFlags=None):
        sid = str(id)
        name = self._route(sid)
        sp = self.sources.get(name)
        if not sp:
            return self._novel_result("错误", f"未找到对应源：{sid[:50]}")
        try:
            return sp.playerContent(flag, sid, vipFlags)
        except Exception as e:
            print(f"[聚合搜索] {name} 正文异常: {e}")
            return self._novel_result("错误", f"发生异常: {e}")

    def _novel_result(self, title, content):
        data = {"title": title, "content": content}
        return {
            "parse": 0,
            "playUrl": "",
            "url": "novel://" + json.dumps(data, ensure_ascii=False),
            "header": "",
        }

    def isVideoFormat(self, url):
        return False

    def manualVideoCheck(self):
        return False

    def destroy(self):
        for sp in self.sources.values():
            try:
                sp.destroy()
            except Exception:
                pass

    def localProxy(self, param):
        return None

# ============ 内嵌子源（兜底） ============
# 由 scripts/sync_embedded.py 自动生成：当 app 缓存/本地没有子源 .py 时，
# 聚合源用内嵌副本也能加载。修改子源后请重跑 scripts/sync_embedded.py。
# >>> EMBEDDED START >>>
_EMBEDDED = {
    "燃文小说": "# -*- coding: utf-8 -*-\n# PickTV / PeekPro 小说源 - 燃文小说\n# 站点：https://www.ranwen.la\nimport re\nimport json\nimport base64\nimport time\nimport urllib.parse\n\nfrom base.spider import Spider\nfrom bs4 import BeautifulSoup\nimport requests\n\n\nclass Spider(Spider):\n    def getName(self):\n        return \"燃文小说\"\n\n    def init(self, extend=\"\"):\n        self.host = \"https://ranwen.la\"  # 用裸域名更稳；站点会在桌面/移动模板间轮换，解析器已兼容两种\n        self.session = requests.Session()\n        self.session.headers.update({\n            \"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36\",\n            \"Referer\": self.host,\n            \"Accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8\",\n            \"Accept-Language\": \"zh-CN,zh;q=0.9\",\n        })\n        # 不走系统代理：本地 Clash 等代理会导致直连站点超时\n        if hasattr(self.session, \"trust_env\"):\n            self.session.trust_env = False\n        self.classes = [\n            (\"1\", \"玄幻修真\"), (\"2\", \"重生穿越\"), (\"3\", \"都市小说\"),\n            (\"4\", \"军史小说\"), (\"5\", \"网游小说\"), (\"6\", \"科幻小说\"),\n            (\"7\", \"灵异小说\"), (\"8\", \"言情小说\"), (\"9\", \"其他小说\"),\n        ]\n\n    # ---------------- 工具 ----------------\n    def _fix_url(self, url):\n        if not url:\n            return \"\"\n        if url.startswith(\"http\"):\n            return url\n        if url.startswith(\"//\"):\n            return \"https:\" + url\n        if url.startswith(\"/\"):\n            return self.host + url\n        return self.host + \"/\" + url\n\n    def _fetch(self, url, timeout=20, tries=3, data=None):\n        for i in range(tries):\n            try:\n                if data is not None:\n                    resp = self.session.post(url, data=data, timeout=timeout)\n                else:\n                    resp = self.session.get(url, timeout=timeout)\n                if resp.status_code == 200:\n                    resp.encoding = \"utf-8\"\n                    return resp.text\n            except Exception as e:\n                print(f\"[燃文小说 Fetch Error] {url} -> {e}\")\n            if i < tries - 1:\n                time.sleep(1)\n        return \"\"\n\n    def _og(self, soup, name):\n        node = soup.select_one('meta[property=\"og:%s\"]' % name)\n        return node.get(\"content\", \"\").strip() if node else \"\"\n\n    # ---------------- 首页 / 分类 ----------------\n    def homeContent(self, filter=False):\n        return {\"class\": [{\"type_id\": tid, \"type_name\": name} for tid, name in self.classes]}\n\n    def _parse_row(self, li):\n        # 兼容站点两种列表模板：\n        # 1) 桌面版：ul.txt-list li -> span.s2 a[href*='/oorw/']\n        # 2) 移动版：li（如 .ph_list li）直接包含 a[href*='/oorw/']，且页面无 <img>，封面按书号合成\n        a = li.select_one(\"span.s2 a[href*='/oorw/']\") or li.select_one(\"a[href*='/oorw/']\")\n        if not a:\n            return None\n        href = a.get(\"href\", \"\")\n        m = re.search(r\"/oorw/(\\d+)/\", href)\n        if not m:\n            return None\n        bid = m.group(1)\n        title = a.get_text(strip=True)\n        title = re.sub(r\"^\\[[^\\]]*\\]\\s*\", \"\", title)\n        chap = li.select_one(\"span.s3 a\")\n        author = li.select_one(\"span.s4\") or li.select_one(\"span.s5 a[href*='/author/']\")\n        if author is None:\n            author = li.select_one(\"a[href*='/author/']\")\n        remark = \"\"\n        if author:\n            remark = author.get_text(strip=True)\n        if chap:\n            remark = (remark + \" \" + chap.get_text(strip=True)).strip()\n        return {\n            \"vod_id\": f\"/oorw/{bid}/\",\n            \"vod_name\": title or (\"书籍\" + bid),\n            # 移动版页面没有 <img>，但 /img/{id}.jpg 封面一直有效，统一按书号合成\n            \"vod_pic\": f\"{self.host}/img/{bid}.jpg\",\n            \"vod_remarks\": remark,\n        }\n\n    def _parse_rows(self, soup):\n        videos, seen = [], set()\n        lis = soup.select(\"ul.txt-list li\")\n        if not lis:\n            # 移动版模板没有 ul.txt-list，取所有包含 /oorw/ 链接的 li\n            lis = [li for li in soup.select(\"li\") if li.select_one(\"a[href*='/oorw/']\")]\n        for li in lis:\n            b = self._parse_row(li)\n            if b and b[\"vod_id\"] not in seen:\n                seen.add(b[\"vod_id\"])\n                videos.append(b)\n        return videos\n\n\n    def homeVideoContent(self):\n        html = self._fetch(self.host)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        return {\"list\": self._parse_rows(soup)[:60]}\n\n    def categoryContent(self, tid, pg, filter=False, extend=\"\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        url = f\"{self.host}/fenlei/{tid}/{pg}.html\"\n        html = self._fetch(url)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = self._parse_rows(soup)\n        # 分页总数：取 lastupdate 分页链接中的最大页号\n        pages = []\n        for a in soup.select(\"a[href*='/fenlei/lastupdate_']\"):\n            m = re.search(r\"lastupdate_\\d+_\\d+_\\d+_(\\d+)\\.html\", a.get(\"href\", \"\"))\n            if m:\n                pages.append(int(m.group(1)))\n        pagecount = max(pages) if pages else 1\n        return {\"list\": videos, \"page\": pg, \"pagecount\": pagecount, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 搜索 ----------------\n    def searchContent(self, key, quick=False, pg=\"1\"):\n        if int(pg or 1) > 1:\n            return {\"list\": [], \"page\": 1, \"pagecount\": 1, \"limit\": 20, \"total\": 0}\n        html = self._fetch(f\"{self.host}/search.html\", data={\"s\": key})\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = self._parse_rows(soup)\n        return {\"list\": videos, \"page\": 1, \"pagecount\": 1, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 详情 / 目录 ----------------\n    def _collect_toc_page(self, html, bid, chapters):\n        soup = BeautifulSoup(html, \"html.parser\")\n        for ul in soup.select(\"ul.section-list.ycxsid\"):\n            for li in ul.select(\"li\"):\n                a = li.select_one(\"a\")\n                if not a:\n                    continue\n                # onclick=\"read_tz(9876032);\" 或 onclick=\"amvzmchq(9876032);\"\n                m = re.search(r\"\\w+\\((\\d+)\\);\", a.get(\"onclick\", \"\"))\n                href = a.get(\"href\", \"\")\n                cid = None\n                if m:\n                    cid = m.group(1)\n                else:\n                    m2 = re.search(r\"/books/%s/(\\d+)\\.html\" % bid, href)\n                    if m2:\n                        cid = m2.group(1)\n                if not cid:\n                    continue\n                title = a.get_text(strip=True)\n                if cid not in chapters:\n                    chapters[cid] = (title, f\"{self.host}/books/{bid}/{cid}.html\")\n\n    def detailContent(self, ids):\n        ids = ids if isinstance(ids, list) else [ids]\n        rid = str(ids[0])\n        if not rid.startswith((\"http\", \"/\")):\n            rid = \"/\" + rid.lstrip(\"/\")\n        url = self._fix_url(rid)\n        html = self._fetch(url)\n        if not html:\n            return {}\n        soup = BeautifulSoup(html, \"html.parser\")\n        title = self._og(soup, \"novel:book_name\") or self._og(soup, \"title\")\n        author = self._og(soup, \"novel:author\")\n        pic = self._fix_url(self._og(soup, \"image\"))\n        category = self._og(soup, \"novel:category\")\n        status = self._og(soup, \"novel:status\")\n        desc = self._og(soup, \"description\") or \"\"\n        # 章节目录入口 /books/{bid}/ml1.html\n        toc_url = \"\"\n        for a in soup.select(\"a[href*='/books/']\"):\n            t = a.get_text(strip=True)\n            if \"目录\" in t or \"章节\" in t:\n                m = re.search(r\"/books/(\\d+)/ml\\d+\\.html\", a.get(\"href\", \"\"))\n                if m:\n                    toc_url = a.get(\"href\", \"\")\n                    bid = m.group(1)\n                    break\n        chapters = {}\n        if toc_url:\n            toc_url = self._fix_url(toc_url)\n            bid = re.search(r\"/books/(\\d+)/\", toc_url).group(1)\n            current = toc_url\n            for _ in range(60):\n                thtml = self._fetch(current)\n                if not thtml:\n                    break\n                before = len(chapters)\n                self._collect_toc_page(thtml, bid, chapters)\n                # 下一页\n                nxt = \"\"\n                for a in BeautifulSoup(thtml, \"html.parser\").select(\"a[href*='/ml']\"):\n                    if a.get_text(strip=True) == \"下一页\":\n                        nxt = a.get(\"href\", \"\")\n                        break\n                if not nxt or len(chapters) == before:\n                    break\n                current = self._fix_url(nxt)\n        vod_play_url = \"#\".join([f\"{t}${u}\" for cid, (t, u) in chapters.items()])\n        return {\n            \"list\": [{\n                \"vod_id\": url.replace(self.host, \"\"),\n                \"vod_name\": title or (\"书籍\"),\n                \"vod_pic\": pic,\n                \"vod_author\": author,\n                \"type_name\": category,\n                \"vod_content\": f\"作者：{author}  {category}  {status}\\n\\n{desc}\",\n                \"vod_play_from\": \"燃文小说\",\n                \"vod_play_url\": vod_play_url,\n            }]\n        }\n\n    # ---------------- 章节正文 ----------------\n    _FILLER = re.compile(\n        r\"^(书香门第.*|附：.*|={3,}|【全本校对】.*|作者[:：]\\s*\\S+$|内容简介[:：].*|请勿开启浏览器阅读模式.*|相邻推荐:?.*)$\"\n    )\n\n    def _decode_content(self, html):\n        \"\"\"正文可能是 base64 混淆（yfbl.bfjlke），也可能是明文 <p>。\"\"\"\n        b64s = re.findall(r\"[\\w$]+\\.\\w+\\(['\\\"]([A-Za-z0-9+/=]{40,})['\\\"]\\)\", html)\n        if b64s:\n            chunks = []\n            for b in b64s:\n                try:\n                    chunks.append(base64.b64decode(b).decode(\"utf-8\", \"ignore\"))\n                except Exception:\n                    continue\n            raw = \"\".join(chunks)\n            cs = BeautifulSoup(raw, \"html.parser\")\n            paras = []\n            for p in cs.select(\"p\"):\n                t = p.get_text(strip=True)\n                if t and not self._FILLER.match(t):\n                    paras.append(t)\n            return \"\\n\\n\".join(paras)\n        # 明文 <p> 版本\n        soup = BeautifulSoup(html, \"html.parser\")\n        wr = soup.select_one(\"div.word_read\")\n        paras = []\n        if wr:\n            for p in wr.select(\"p\"):\n                t = p.get_text(strip=True)\n                if t and not self._FILLER.match(t):\n                    paras.append(t)\n        return \"\\n\\n\".join(paras)\n\n    def playerContent(self, flag, id, vipFlags=None):\n        url = id if str(id).startswith(\"http\") else self._fix_url(id)\n        try:\n            m = re.search(r\"/books/\\d+/(\\d+)\\.html\", url)\n            base_cid = m.group(1) if m else None\n            title = \"\"\n            parts = []\n            current = url\n            for _ in range(20):\n                html = self._fetch(current)\n                if not html:\n                    break\n                soup = BeautifulSoup(html, \"html.parser\")\n                if not title:\n                    h3 = soup.select_one(\"div.word_read h3\")\n                    if h3:\n                        title = re.sub(r\"[（(]第\\d+页[)）]\\s*$\", \"\", h3.get_text(strip=True))\n                text = self._decode_content(html)\n                if text:\n                    parts.append(text)\n                nxt = \"\"\n                for a in soup.select(\"a\"):\n                    if a.get_text(strip=True) in (\"下一页\", \"下一章\"):\n                        nxt = a.get(\"href\", \"\")\n                        break\n                if not nxt:\n                    break\n                nm = re.search(r\"/books/\\d+/(\\d+)(?:_\\d+)?\\.html\", nxt)\n                if not nm:\n                    break\n                if base_cid and nm.group(1) != base_cid:\n                    break\n                current = self._fix_url(nxt)\n            content = re.sub(r\"\\n\\s*\\n+\", \"\\n\\n\", \"\\n\\n\".join(parts)).strip()\n            if not content:\n                content = \"未获取到章节内容\"\n            return self._novel_result(title or \"章节\", content)\n        except Exception as e:\n            print(f\"[燃文小说 playerContent] {e}\")\n            return self._novel_result(\"错误\", f\"发生异常: {e}\")\n\n    def _novel_result(self, title, content):\n        data = {\"title\": title, \"content\": content}\n        return {\n            \"parse\": 0,\n            \"playUrl\": \"\",\n            \"url\": \"novel://\" + json.dumps(data, ensure_ascii=False),\n            \"header\": \"\",\n        }\n\n    def isVideoFormat(self, url):\n        return False\n\n    def manualVideoCheck(self):\n        return False\n\n    def destroy(self):\n        try:\n            if self.session:\n                self.session.close()\n        except Exception:\n            pass\n\n    def localProxy(self, param):\n        return None",
    "笔趣阁": "# -*- coding: utf-8 -*-\n# PickTV / PeekPro 小说源 - 笔趣阁\n# 站点：https://www.biquwu.cc（与灯笔小说同模板，可互为备份）\nimport re\nimport json\nimport time\nimport urllib.parse\n\nfrom base.spider import Spider\nfrom bs4 import BeautifulSoup\nimport requests\n\n\nclass Spider(Spider):\n    def getName(self):\n        return \"笔趣阁\"\n\n    def init(self, extend=\"\"):\n        self.host = \"https://www.biquwu.cc\"\n        self.session = requests.Session()\n        self.session.headers.update({\n            \"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36\",\n            \"Referer\": self.host,\n            \"Accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8\",\n            \"Accept-Language\": \"zh-CN,zh;q=0.9\",\n        })\n        # 不走系统代理：本地 Clash 等代理会导致直连站点超时\n        if hasattr(self.session, \"trust_env\"):\n            self.session.trust_env = False\n        self.classes = [\n            (\"1\", \"玄幻\"), (\"2\", \"武侠\"), (\"3\", \"都市\"),\n            (\"4\", \"历史\"), (\"5\", \"网游\"), (\"6\", \"科幻\"),\n            (\"7\", \"言情\"), (\"8\", \"其他\"),\n        ]\n\n    # ---------------- 工具 ----------------\n    def _fix_url(self, url):\n        if not url:\n            return \"\"\n        if url.startswith(\"http\"):\n            return url\n        if url.startswith(\"//\"):\n            return \"https:\" + url\n        if url.startswith(\"/\"):\n            return self.host + url\n        return self.host + \"/\" + url\n\n    def _fetch(self, url, timeout=20, tries=3):\n        for i in range(tries):\n            try:\n                resp = self.session.get(url, timeout=timeout)\n                if resp.status_code == 200:\n                    resp.encoding = \"utf-8\"\n                    return resp.text\n            except Exception as e:\n                print(f\"[笔趣阁 Fetch Error] {url} -> {e}\")\n            if i < tries - 1:\n                time.sleep(1)\n        return \"\"\n\n    def _og(self, soup, name):\n        node = soup.select_one('meta[property=\"og:%s\"]' % name)\n        return node.get(\"content\", \"\").strip() if node else \"\"\n\n    # ---------------- 首页 / 分类 ----------------\n    def homeContent(self, filter=False):\n        return {\"class\": [{\"type_id\": tid, \"type_name\": name} for tid, name in self.classes]}\n\n    def _book_id(self, href):\n        # /biquge/35_35912/  ->  35_35912/\n        m = re.search(r\"/(\\d+)_(\\d+)/\", href or \"\")\n        return f\"{m.group(1)}_{m.group(2)}/\" if m else \"\"\n\n    def _parse_dl(self, dl):\n        a = dl.select_one(\"h3 a\") or dl.select_one(\"dt a\")\n        if not a:\n            return None\n        href = a.get(\"href\", \"\")\n        bid = self._book_id(href)\n        if not bid:\n            return None\n        img = dl.select_one(\"dt img\")\n        pic = img.get(\"src\", \"\") if img else \"\"\n        title = a.get_text(strip=True) or a.get(\"title\", \"\")\n        title = re.sub(r\"^\\[[^\\]]*\\]\\s*\", \"\", title)\n        author_node = dl.select_one(\".book_other\")\n        author = author_node.get_text(\" \", strip=True) if author_node else \"\"\n        author = re.sub(r\"^作者[:：]\\s*\", \"\", author)\n        status_node = dl.select_one(\".book_other + .book_other\")\n        status = status_node.get_text(strip=True) if status_node else \"\"\n        return {\n            \"vod_id\": bid,\n            \"vod_name\": title or (\"书籍\" + bid),\n            \"vod_pic\": self._fix_url(pic),\n            \"vod_remarks\": f\"{author} {status}\".strip(),\n        }\n\n    def homeVideoContent(self):\n        html = self._fetch(self.host)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos, seen = [], set()\n\n        def add(book):\n            if book and book[\"vod_id\"] not in seen:\n                seen.add(book[\"vod_id\"])\n                videos.append(book)\n\n        for card in soup.select(\"div.col-4.recommend\"):\n            a = card.select_one(\"div.pic a.img[href]\") or card.select_one(\"h3 a[href]\")\n            if not a:\n                continue\n            bid = self._book_id(a.get(\"href\", \"\"))\n            if not bid:\n                continue\n            img = card.select_one(\"div.pic img\")\n            pic = img.get(\"src\", \"\") if img else \"\"\n            h3 = card.select_one(\"h3 a\")\n            title = h3.get_text(strip=True) if h3 else (img.get(\"alt\", \"\") if img else \"\")\n            info = card.select_one(\"p.info\")\n            remark = info.get_text(\" \", strip=True) if info else \"\"\n            add({\n                \"vod_id\": bid,\n                \"vod_name\": title or (\"书籍\" + bid),\n                \"vod_pic\": self._fix_url(pic),\n                \"vod_remarks\": remark,\n            })\n        for row in soup.select(\"div.tab-content\"):\n            a = row.select_one(\"div.bookname a[href]\")\n            if not a:\n                continue\n            bid = self._book_id(a.get(\"href\", \"\"))\n            if not bid:\n                continue\n            chap = row.select_one(\"div.chap a\")\n            author = row.select_one(\"div.author\")\n            remark = \"\"\n            if chap:\n                remark = \"更新：\" + chap.get_text(strip=True)\n            if author:\n                remark = (author.get_text(strip=True) + \" \" + remark).strip()\n            add({\n                \"vod_id\": bid,\n                \"vod_name\": a.get_text(strip=True) or (\"书籍\" + bid),\n                \"vod_pic\": \"\",\n                \"vod_remarks\": remark,\n            })\n        return {\"list\": videos[:60]}\n\n    def categoryContent(self, tid, pg, filter=False, extend=\"\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        url = f\"{self.host}/list{tid}/\" if pg <= 1 else f\"{self.host}/list{tid}/{pg}.html\"\n        html = self._fetch(url)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = [b for b in (self._parse_dl(dl) for dl in soup.select(\"dl\")) if b]\n        pages = [int(m.group(1)) for a in soup.select(\"a[href*='/list']\") for m in [re.search(r\"/list\\d+/(\\d+)\\.html\", a.get(\"href\", \"\"))] if m]\n        pagecount = max(pages) if pages else 1\n        return {\"list\": videos, \"page\": pg, \"pagecount\": pagecount, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 搜索 ----------------\n    def searchContent(self, key, quick=False, pg=\"1\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        # 本站搜索 301 到 www.fsshu.com（HTTP），直连其 https 更稳\n        url = f\"https://www.fsshu.com/search.php?q={urllib.parse.quote(key)}&p={pg}\"\n        html = self._fetch(url)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = [b for b in (self._parse_dl(dl) for dl in soup.select(\"dl\")) if b]\n        pages = []\n        for a in soup.select(\"a[href*='search.php']\"):\n            m = re.search(r\"[?&]p=(\\d+)\", a.get(\"href\", \"\"))\n            if m:\n                pages.append(int(m.group(1)))\n        pagecount = max(pages) if pages else 1\n        return {\"list\": videos, \"page\": pg, \"pagecount\": pagecount, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 详情 / 目录 ----------------\n    def _toc_pages(self, soup):\n        pages = []\n        for a in soup.select(\"a[href*='index_']\"):\n            m = re.search(r\"index_(\\d+)\\.html\", a.get(\"href\", \"\"))\n            if m:\n                pages.append(int(m.group(1)))\n        return max(pages) if pages else 1\n\n    def _collect_toc(self, soup, chapters):\n        for bl in soup.select(\"div.book_list\"):\n            prev = None\n            for sib in (bl.parent.find_all(recursive=False) if bl.parent else []):\n                if sib is bl:\n                    break\n                if sib.name in (\"b\", \"h2\", \"h3\", \"h4\"):\n                    prev = sib\n            if prev and \"最新12章节\" in prev.get_text():\n                continue\n            for a in bl.select(\"ul.row li a[href]\"):\n                href = a.get(\"href\", \"\")\n                if re.search(r\"/biquge/\\d+_\\d+/c\\d+\\.html\", href) and href not in chapters:\n                    chapters[href] = a.get_text(strip=True)\n\n    def detailContent(self, ids):\n        ids = ids if isinstance(ids, list) else [ids]\n        rid = str(ids[0])\n        if not rid.startswith((\"http\", \"/\")):\n            rid = \"/biquge/\" + rid.lstrip(\"/\")\n        url = self._fix_url(rid)\n        if not url.endswith(\"/\"):\n            url += \"/\"\n        html = self._fetch(url)\n        if not html:\n            return {}\n        soup = BeautifulSoup(html, \"html.parser\")\n        title = self._og(soup, \"novel:book_name\") or self._og(soup, \"title\")\n        author = self._og(soup, \"novel:author\")\n        pic = self._fix_url(self._og(soup, \"image\"))\n        category = self._og(soup, \"novel:category\")\n        status = self._og(soup, \"novel:status\")\n        desc = self._og(soup, \"description\") or \"\"\n        total = self._toc_pages(soup)\n        chapters = {}\n        for page in range(1, total + 1):\n            toc_url = url if page <= 1 else url.rstrip(\"/\") + f\"/index_{page}.html\"\n            thtml = self._fetch(toc_url)\n            if not thtml:\n                continue\n            self._collect_toc(BeautifulSoup(thtml, \"html.parser\"), chapters)\n        vod_play_url = \"#\".join([f\"{t}${self._fix_url(h)}\" for h, t in chapters.items()])\n        return {\n            \"list\": [{\n                \"vod_id\": url.replace(self.host, \"\"),\n                \"vod_name\": title or (\"书籍\" + url.rstrip(\"/\").split(\"/\")[-1]),\n                \"vod_pic\": pic,\n                \"vod_author\": author,\n                \"type_name\": category,\n                \"vod_content\": f\"作者：{author}  {category}  {status}\\n\\n{desc}\",\n                \"vod_play_from\": \"笔趣阁\",\n                \"vod_play_url\": vod_play_url,\n            }]\n        }\n\n    # ---------------- 章节正文 ----------------\n    def playerContent(self, flag, id, vipFlags=None):\n        url = id if str(id).startswith(\"http\") else self._fix_url(id)\n        try:\n            m = re.search(r\"/c(\\d+)(?:_\\d+)?\\.html\", url)\n            base_cid = m.group(1) if m else None\n            title = \"\"\n            parts = []\n            current = url\n            for _ in range(20):\n                html = self._fetch(current)\n                if not html:\n                    break\n                soup = BeautifulSoup(html, \"html.parser\")\n                if not title:\n                    h1 = soup.select_one(\"h1\")\n                    if h1:\n                        t = h1.get_text(strip=True)\n                        title = re.sub(r\"[-－]\\s*《.*》\\s*$\", \"\", t)\n                art = soup.select_one(\"article\")\n                if art:\n                    for line in art.get_text(\"\\n\").split(\"\\n\"):\n                        line = line.strip().replace(\"\\u3000\", \" \").strip()\n                        if not line:\n                            continue\n                        if re.match(r\"^第\\(\\d+/\\d+\\)页$\", line):\n                            continue\n                        parts.append(line)\n                nxt = \"\"\n                for a in soup.select(\"a\"):\n                    if a.get_text(strip=True) == \"下一页\":\n                        nxt = a.get(\"href\", \"\")\n                        break\n                if not nxt:\n                    break\n                nm = re.search(r\"/c(\\d+)(?:_\\d+)?\\.html\", nxt)\n                if not nm:\n                    break\n                if base_cid and nm.group(1) != base_cid:\n                    break\n                current = self._fix_url(nxt)\n            content = re.sub(r\"\\n\\s*\\n+\", \"\\n\\n\", \"\\n\\n\".join(parts)).strip()\n            if not content:\n                content = \"未获取到章节内容\"\n            return self._novel_result(title or \"章节\", content)\n        except Exception as e:\n            print(f\"[笔趣阁 playerContent] {e}\")\n            return self._novel_result(\"错误\", f\"发生异常: {e}\")\n\n    def _novel_result(self, title, content):\n        data = {\"title\": title, \"content\": content}\n        return {\n            \"parse\": 0,\n            \"playUrl\": \"\",\n            \"url\": \"novel://\" + json.dumps(data, ensure_ascii=False),\n            \"header\": \"\",\n        }\n\n    def isVideoFormat(self, url):\n        return False\n\n    def manualVideoCheck(self):\n        return False\n\n    def destroy(self):\n        try:\n            if self.session:\n                self.session.close()\n        except Exception:\n            pass\n\n    def localProxy(self, param):\n        return None\n",
    "灯笔小说": "# -*- coding: utf-8 -*-\n# PickTV / PeekPro 小说源 - 灯笔小说\n# 站点：https://www.dengbi.net\nimport re\nimport json\nimport time\nimport urllib.parse\n\nfrom base.spider import Spider\nfrom bs4 import BeautifulSoup\nimport requests\n\n\nclass Spider(Spider):\n    def getName(self):\n        return \"灯笔小说\"\n\n    def init(self, extend=\"\"):\n        self.host = \"https://www.dengbi.net\"\n        self.session = requests.Session()\n        self.session.headers.update({\n            \"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36\",\n            \"Referer\": self.host,\n            \"Accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8\",\n            \"Accept-Language\": \"zh-CN,zh;q=0.9\",\n        })\n        # 不走系统代理：本地 Clash 等代理会导致直连站点超时\n        if hasattr(self.session, \"trust_env\"):\n            self.session.trust_env = False\n        self.classes = [\n            (\"1\", \"玄幻\"), (\"2\", \"武侠\"), (\"3\", \"都市\"),\n            (\"4\", \"历史\"), (\"5\", \"网游\"), (\"6\", \"科幻\"),\n            (\"7\", \"言情\"), (\"8\", \"其他\"),\n        ]\n\n    # ---------------- 工具 ----------------\n    def _fix_url(self, url):\n        if not url:\n            return \"\"\n        if url.startswith(\"http\"):\n            return url\n        if url.startswith(\"//\"):\n            return \"https:\" + url\n        if url.startswith(\"/\"):\n            return self.host + url\n        return self.host + \"/\" + url\n\n    def _fetch(self, url, timeout=20, tries=3):\n        for i in range(tries):\n            try:\n                resp = self.session.get(url, timeout=timeout)\n                if resp.status_code == 200:\n                    resp.encoding = \"utf-8\"\n                    return resp.text\n            except Exception as e:\n                print(f\"[灯笔小说 Fetch Error] {url} -> {e}\")\n            if i < tries - 1:\n                time.sleep(1)\n        return \"\"\n\n    def _og(self, soup, name):\n        node = soup.select_one('meta[property=\"og:%s\"]' % name)\n        return node.get(\"content\", \"\").strip() if node else \"\"\n\n    # ---------------- 首页 / 分类 ----------------\n    def homeContent(self, filter=False):\n        return {\"class\": [{\"type_id\": tid, \"type_name\": name} for tid, name in self.classes]}\n\n    def _book_id(self, href):\n        m = re.search(r\"/(\\d+)/(\\d+)/\", href or \"\")\n        return f\"{m.group(1)}/{m.group(2)}/\" if m else \"\"\n\n    def _parse_dl(self, dl):\n        a = dl.select_one(\"h3 a\") or dl.select_one(\"dt a\")\n        if not a:\n            return None\n        href = a.get(\"href\", \"\")\n        bid = self._book_id(href)\n        if not bid:\n            return None\n        img = dl.select_one(\"dt img\")\n        pic = img.get(\"src\", \"\") if img else \"\"\n        title = a.get_text(strip=True) or a.get(\"title\", \"\")\n        title = re.sub(r\"^\\[[^\\]]*\\]\\s*\", \"\", title)\n        author_node = dl.select_one(\".book_other\")\n        author = author_node.get_text(\" \", strip=True) if author_node else \"\"\n        author = re.sub(r\"^作者[:：]\\s*\", \"\", author)\n        status_node = dl.select_one(\".book_other + .book_other\")\n        status = status_node.get_text(strip=True) if status_node else \"\"\n        return {\n            \"vod_id\": bid,\n            \"vod_name\": title or (\"书籍\" + bid),\n            \"vod_pic\": self._fix_url(pic),\n            \"vod_remarks\": f\"{author} {status}\".strip(),\n        }\n\n    def homeVideoContent(self):\n        html = self._fetch(self.host)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos, seen = [], set()\n\n        def add(book):\n            if book and book[\"vod_id\"] not in seen:\n                seen.add(book[\"vod_id\"])\n                videos.append(book)\n\n        # 顶部推荐卡片（带封面）\n        for card in soup.select(\"div.col-4.recommend\"):\n            a = card.select_one(\"div.pic a.img[href]\")\n            if not a:\n                a = card.select_one(\"h3 a[href]\") or card.select_one(\"a[href]\")\n            if not a:\n                continue\n            bid = self._book_id(a.get(\"href\", \"\"))\n            if not bid:\n                continue\n            img = card.select_one(\"div.pic img\")\n            pic = img.get(\"src\", \"\") if img else \"\"\n            h3 = card.select_one(\"h3 a\")\n            title = h3.get_text(strip=True) if h3 else (img.get(\"alt\", \"\") if img else \"\")\n            info = card.select_one(\"p.info\")\n            remark = info.get_text(\" \", strip=True) if info else \"\"\n            add({\n                \"vod_id\": bid,\n                \"vod_name\": title or (\"书籍\" + bid),\n                \"vod_pic\": self._fix_url(pic),\n                \"vod_remarks\": remark,\n            })\n        # 最新入库 / 最新更新 列表\n        for row in soup.select(\"div.tab-content\"):\n            a = row.select_one(\"div.bookname a[href]\")\n            if not a:\n                continue\n            bid = self._book_id(a.get(\"href\", \"\"))\n            if not bid:\n                continue\n            chap = row.select_one(\"div.chap a\")\n            author = row.select_one(\"div.author\")\n            remark = \"\"\n            if chap:\n                remark = \"更新：\" + chap.get_text(strip=True)\n            if author:\n                remark = (author.get_text(strip=True) + \" \" + remark).strip()\n            add({\n                \"vod_id\": bid,\n                \"vod_name\": a.get_text(strip=True) or (\"书籍\" + bid),\n                \"vod_pic\": \"\",\n                \"vod_remarks\": remark,\n            })\n        return {\"list\": videos[:60]}\n\n    def categoryContent(self, tid, pg, filter=False, extend=\"\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        url = f\"{self.host}/list{tid}/\" if pg <= 1 else f\"{self.host}/list{tid}/{pg}.html\"\n        html = self._fetch(url)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = [b for b in (self._parse_dl(dl) for dl in soup.select(\"dl\")) if b]\n        # 分页总数：取 pager 中 index 最大数字（» 指向末页）\n        pages = [int(m.group(1)) for a in soup.select(\"a[href*='/list']\") for m in [re.search(r\"/list\\d+/(\\d+)\\.html\", a.get(\"href\", \"\"))] if m]\n        pagecount = max(pages) if pages else 1\n        return {\"list\": videos, \"page\": pg, \"pagecount\": pagecount, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 搜索 ----------------\n    def searchContent(self, key, quick=False, pg=\"1\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        url = f\"{self.host}/search.php?q={urllib.parse.quote(key)}&p={pg}\"\n        html = self._fetch(url)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = [b for b in (self._parse_dl(dl) for dl in soup.select(\"dl\")) if b]\n        pages = []\n        for a in soup.select(\"a[href*='search.php']\"):\n            m = re.search(r\"[?&]p=(\\d+)\", a.get(\"href\", \"\"))\n            if m:\n                pages.append(int(m.group(1)))\n        pagecount = max(pages) if pages else 1\n        return {\"list\": videos, \"page\": pg, \"pagecount\": pagecount, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 详情 / 目录 ----------------\n    def _toc_pages(self, soup):\n        pages = []\n        for a in soup.select(\"a[href*='index_']\"):\n            m = re.search(r\"index_(\\d+)\\.html\", a.get(\"href\", \"\"))\n            if m:\n                pages.append(int(m.group(1)))\n        return max(pages) if pages else 1\n\n    def _collect_toc(self, soup, chapters):\n        for bl in soup.select(\"div.book_list\"):\n            # 跳过“最新12章节”块，避免与全章节列表重复\n            prev = None\n            for sib in (bl.parent.find_all(recursive=False) if bl.parent else []):\n                if sib is bl:\n                    break\n                if sib.name in (\"b\", \"h2\", \"h3\", \"h4\"):\n                    prev = sib\n            if prev and \"最新12章节\" in prev.get_text():\n                continue\n            for a in bl.select(\"ul.row li a[href]\"):\n                href = a.get(\"href\", \"\")\n                if re.search(r\"/\\d+/\\d+/\\d+\\.html\", href) and href not in chapters:\n                    chapters[href] = a.get_text(strip=True)\n\n    def detailContent(self, ids):\n        ids = ids if isinstance(ids, list) else [ids]\n        rid = str(ids[0])\n        if not rid.startswith((\"http\", \"/\")):\n            rid = \"/\" + rid.lstrip(\"/\")\n        url = self._fix_url(rid)\n        if not url.endswith(\"/\"):\n            url += \"/\"\n        html = self._fetch(url)\n        if not html:\n            return {}\n        soup = BeautifulSoup(html, \"html.parser\")\n        title = self._og(soup, \"novel:book_name\") or self._og(soup, \"title\")\n        author = self._og(soup, \"novel:author\")\n        pic = self._fix_url(self._og(soup, \"image\"))\n        category = self._og(soup, \"novel:category\")\n        status = self._og(soup, \"novel:status\")\n        desc = self._og(soup, \"description\") or \"\"\n        # 目录分页\n        total = self._toc_pages(soup)\n        chapters = {}\n        for page in range(1, total + 1):\n            toc_url = url if page <= 1 else url.rstrip(\"/\") + f\"/index_{page}.html\"\n            thtml = self._fetch(toc_url)\n            if not thtml:\n                continue\n            self._collect_toc(BeautifulSoup(thtml, \"html.parser\"), chapters)\n        vod_play_url = \"#\".join([f\"{t}${self._fix_url(h)}\" for h, t in chapters.items()])\n        return {\n            \"list\": [{\n                \"vod_id\": url.replace(self.host, \"\"),\n                \"vod_name\": title or (\"书籍\" + url.rstrip(\"/\").split(\"/\")[-1]),\n                \"vod_pic\": pic,\n                \"vod_author\": author,\n                \"type_name\": category,\n                \"vod_content\": f\"作者：{author}  {category}  {status}\\n\\n{desc}\",\n                \"vod_play_from\": \"灯笔小说\",\n                \"vod_play_url\": vod_play_url,\n            }]\n        }\n\n    # ---------------- 章节正文 ----------------\n    def playerContent(self, flag, id, vipFlags=None):\n        url = id if str(id).startswith(\"http\") else self._fix_url(id)\n        try:\n            m = re.search(r\"/(\\d+)\\.html\", url)\n            base_cid = m.group(1) if m else None\n            title = \"\"\n            parts = []\n            current = url\n            for _ in range(20):\n                html = self._fetch(current)\n                if not html:\n                    break\n                soup = BeautifulSoup(html, \"html.parser\")\n                if not title:\n                    h1 = soup.select_one(\"h1\")\n                    if h1:\n                        t = h1.get_text(strip=True)\n                        title = re.sub(r\"[-－]\\s*《.*》\\s*$\", \"\", t)\n                art = soup.select_one(\"article\")\n                if art:\n                    for line in art.get_text(\"\\n\").split(\"\\n\"):\n                        line = line.strip().replace(\"\\u3000\", \" \").strip()\n                        if not line:\n                            continue\n                        if re.match(r\"^第\\(\\d+/\\d+\\)页$\", line):\n                            continue\n                        parts.append(line)\n                nxt = \"\"\n                for a in soup.select(\"a\"):\n                    if a.get_text(strip=True) == \"下一章\":\n                        nxt = a.get(\"href\", \"\")\n                        break\n                if not nxt:\n                    break\n                nm = re.search(r\"/(\\d+)(?:_\\d+)?\\.html\", nxt)\n                if not nm:\n                    break\n                if base_cid and nm.group(1) != base_cid:\n                    break\n                current = self._fix_url(nxt)\n            content = re.sub(r\"\\n\\s*\\n+\", \"\\n\\n\", \"\\n\\n\".join(parts)).strip()\n            if not content:\n                content = \"未获取到章节内容\"\n            return self._novel_result(title or \"章节\", content)\n        except Exception as e:\n            print(f\"[灯笔小说 playerContent] {e}\")\n            return self._novel_result(\"错误\", f\"发生异常: {e}\")\n\n    def _novel_result(self, title, content):\n        data = {\"title\": title, \"content\": content}\n        return {\n            \"parse\": 0,\n            \"playUrl\": \"\",\n            \"url\": \"novel://\" + json.dumps(data, ensure_ascii=False),\n            \"header\": \"\",\n        }\n\n    def isVideoFormat(self, url):\n        return False\n\n    def manualVideoCheck(self):\n        return False\n\n    def destroy(self):\n        try:\n            if self.session:\n                self.session.close()\n        except Exception:\n            pass\n\n    def localProxy(self, param):\n        return None\n",
    "顶点小说": "# -*- coding: utf-8 -*-\n# PickTV / PeekPro 小说源 - 顶点小说\n# 站点：https://www.wxsy.net\nimport re\nimport json\nimport base64\nimport urllib.parse\n\nfrom base.spider import Spider\nfrom bs4 import BeautifulSoup\n\ntry:\n    from curl_cffi import requests as _req\n    CURL_CFFI = True\nexcept Exception:\n    import requests as _req\n    CURL_CFFI = False\n\n\nclass Spider(Spider):\n    def getName(self):\n        return \"顶点小说\"\n\n    def init(self, extend=\"\"):\n        self.host = \"https://www.wxsy.net\"\n        if CURL_CFFI:\n            self.session = _req.Session(impersonate=\"chrome\")\n        else:\n            self.session = _req.Session()\n        self.session.headers.update({\n            \"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36\",\n            \"Referer\": self.host,\n            \"Accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8\",\n            \"Accept-Language\": \"zh-CN,zh;q=0.9\",\n        })\n        # 不走系统代理：本地 Clash 等代理会导致直连站点超时\n        if hasattr(self.session, \"trust_env\"):\n            self.session.trust_env = False\n        print(f\"[顶点小说] HTTP 引擎: {'curl_cffi' if CURL_CFFI else 'requests'}\")\n        self.classes = [\n            (\"1\", \"玄幻修真\"), (\"2\", \"重生穿越\"), (\"3\", \"都市小说\"),\n            (\"4\", \"军史小说\"), (\"5\", \"网游小说\"), (\"6\", \"科幻小说\"),\n            (\"7\", \"灵异小说\"), (\"8\", \"言情小说\"), (\"9\", \"其他小说\"),\n        ]\n\n    # ---------------- 工具 ----------------\n    def _fix_url(self, url):\n        if not url:\n            return \"\"\n        if url.startswith(\"http\"):\n            return url\n        if url.startswith(\"//\"):\n            return \"https:\" + url\n        if url.startswith(\"/\"):\n            return self.host + url\n        return self.host + \"/\" + url\n\n    def _fetch(self, url, timeout=15, data=None):\n        last = None\n        for attempt in range(1, 4):\n            try:\n                if data is not None:\n                    resp = self.session.post(url, data=data, timeout=timeout)\n                else:\n                    resp = self.session.get(url, timeout=timeout)\n                resp.encoding = \"utf-8\"\n                return resp.text\n            except Exception as e:\n                last = e\n                print(f\"[顶点小说] 第{attempt}次失败 {url} -> {e}\")\n                # curl_cffi 异常（如 CA 加载失败、中文路径问题）时自动回退 requests\n                if CURL_CFFI:\n                    try:\n                        if not hasattr(self, \"_req_fallback\"):\n                            import requests as _rq\n                            self._req_fallback = _rq.Session()\n                            self._req_fallback.headers.update(self.session.headers)\n                            self._req_fallback.trust_env = False\n                        if data is not None:\n                            resp = self._req_fallback.post(url, data=data, timeout=timeout)\n                        else:\n                            resp = self._req_fallback.get(url, timeout=timeout)\n                        resp.encoding = \"utf-8\"\n                        return resp.text\n                    except Exception as e2:\n                        last = e2\n        print(f\"[顶点小说 Fetch Error] {url} -> {last}\")\n        return \"\"\n\n    def _og(self, soup, name):\n        node = soup.select_one('meta[property=\"og:%s\"]' % name)\n        return node.get(\"content\", \"\").strip() if node else \"\"\n\n    # ---------------- 首页 / 分类 ----------------\n    def homeContent(self, filter=False):\n        return {\"class\": [{\"type_id\": tid, \"type_name\": name} for tid, name in self.classes]}\n\n    def _parse_item(self, item):\n        a_tag = item.select_one(\"div.image a[href*='/novel/']\") or item.find(\"a\")\n        if not a_tag:\n            return None\n        href = a_tag.get(\"href\", \"\")\n        m = re.search(r\"/novel/(\\d+)/\", href)\n        if not m:\n            return None\n        img = item.select_one(\"div.image img\")\n        pic = img.get(\"src\", \"\") if img else \"\"\n        title_node = item.select_one(\"dt a\")\n        title = title_node.get_text(strip=True) if title_node else \"\"\n        author_node = item.select_one(\"dt span\")\n        author = author_node.get_text(strip=True) if author_node else \"\"\n        if not title:\n            title = a_tag.get_text(strip=True) or a_tag.get(\"title\", \"\")\n        return {\n            \"vod_id\": m.group(1),\n            \"vod_name\": title or (\"书籍\" + m.group(1)),\n            \"vod_pic\": self._fix_url(pic),\n            \"vod_remarks\": author,\n        }\n\n    def homeVideoContent(self):\n        html = self._fetch(self.host)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos, seen = [], set()\n        for item in soup.select(\"div.item\"):\n            book = self._parse_item(item)\n            if book and book[\"vod_id\"] not in seen:\n                seen.add(book[\"vod_id\"])\n                videos.append(book)\n        # 补充分区里的书籍链接\n        for a in soup.select(\"a[href*='/novel/']\"):\n            m = re.search(r\"/novel/(\\d+)/\", a.get(\"href\", \"\"))\n            if not m or m.group(1) in seen:\n                continue\n            seen.add(m.group(1))\n            videos.append({\n                \"vod_id\": m.group(1),\n                \"vod_name\": a.get_text(strip=True) or (\"书籍\" + m.group(1)),\n                \"vod_pic\": \"\",\n                \"vod_remarks\": \"\",\n            })\n        return {\"list\": videos[:40]}\n\n    def categoryContent(self, tid, pg, filter=False, extend=\"\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        url = f\"{self.host}/sort/{tid}/{pg}.html\"\n        html = self._fetch(url)\n        if not html:\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = []\n        for item in soup.select(\"div.item\"):\n            book = self._parse_item(item)\n            if book:\n                videos.append(book)\n        pagecount = self._pagecount(soup, tid, pg)\n        per = max(len(videos), 1)\n        return {\n            \"list\": videos,\n            \"page\": pg,\n            \"pagecount\": pagecount,\n            \"limit\": per,\n            \"total\": pagecount * per,\n        }\n\n    def _pagecount(self, soup, tid, pg):\n        nums = [int(x) for x in re.findall(r\"/sort/lastupdate_%s_0_0_(\\d+)\\.html\" % tid, str(soup))]\n        if nums:\n            return max(nums)\n        return pg + 1 if soup.select_one(\"a[href*='/sort/']\") else pg\n\n    # ---------------- 搜索 ----------------\n    def searchContent(self, key, quick=False, pg=\"1\"):\n        if int(pg or 1) > 1:\n            return {\"list\": [], \"page\": 1, \"pagecount\": 1, \"limit\": 20, \"total\": 0}\n        try:\n            resp = self.session.post(self.host + \"/search.html\", data={\"s\": key}, timeout=15)\n            resp.encoding = \"utf-8\"\n            html = resp.text\n        except Exception as e:\n            print(f\"[顶点小说 Search Error] {e}\")\n            return {\"list\": []}\n        soup = BeautifulSoup(html, \"html.parser\")\n        videos = []\n        for li in soup.select(\"ul.txt-list li\"):\n            a = li.select_one(\"span.s2 a\")\n            if not a:\n                continue\n            m = re.search(r\"/novel/(\\d+)/\", a.get(\"href\", \"\"))\n            if not m:\n                continue\n            cate = li.select_one(\"span.s1\")\n            author = li.select_one(\"span.s3\")\n            remark = (cate.get_text(strip=True) if cate else \"\") + \" \" + (author.get_text(strip=True) if author else \"\")\n            videos.append({\n                \"vod_id\": m.group(1),\n                \"vod_name\": a.get_text(strip=True),\n                \"vod_pic\": \"\",\n                \"vod_remarks\": remark.strip(),\n            })\n        return {\"list\": videos, \"page\": 1, \"pagecount\": 1, \"limit\": 20, \"total\": len(videos)}\n\n    # ---------------- 详情 ----------------\n    def _collect_chapters(self, soup, chapters):\n        uls = soup.select(\"ul.section-list\")\n        if not uls:\n            return\n        ul = uls[-1]  # 章节列表（最后一个；前一个是最新章节）\n        for a in ul.select(\"li a\"):\n            href = a.get(\"href\", \"\")\n            m = re.search(r\"/novel/(\\d+)/read_(\\d+)\\.html\", href)\n            if not m:\n                continue\n            cid = int(m.group(2))\n            chapters[cid] = (a.get_text(strip=True), self._fix_url(href))\n\n    def _toc(self, book_id):\n        chapters = {}\n        html = self._fetch(f\"{self.host}/novel/{book_id}/\")\n        if not html:\n            return []\n        soup = BeautifulSoup(html, \"html.parser\")\n        self._collect_chapters(soup, chapters)\n        page = 1\n        while page <= 30:\n            if len(chapters) < 100:\n                break\n            html2 = self._fetch(f\"{self.host}/novel/{book_id}/chapter_{page}.html\")\n            if not html2:\n                break\n            soup2 = BeautifulSoup(html2, \"html.parser\")\n            before = len(chapters)\n            self._collect_chapters(soup2, chapters)\n            if len(chapters) == before:\n                break\n            sel = soup2.select_one(\"select\")\n            total_pages = 0\n            if sel:\n                total_pages = len([o for o in sel.select(\"option\") if \"chapter_\" in (o.get(\"value\") or \"\")])\n            if total_pages and total_pages <= page:\n                break\n            if not sel and len(chapters) >= 100:\n                pass  # 没有页码选择器时继续尝试下一页\n            page += 1\n        return [chapters[k] for k in sorted(chapters.keys())]\n\n    def detailContent(self, ids):\n        ids = ids if isinstance(ids, list) else [ids]\n        book_id = ids[0]\n        m = re.search(r\"(\\d+)\", str(book_id))\n        if not m:\n            return {}\n        book_id = m.group(1)\n        html = self._fetch(f\"{self.host}/novel/{book_id}/\")\n        if not html:\n            return {}\n        soup = BeautifulSoup(html, \"html.parser\")\n        title = self._og(soup, \"novel:book_name\") or self._og(soup, \"title\")\n        author = self._og(soup, \"novel:author\")\n        pic = self._fix_url(self._og(soup, \"image\"))\n        category = self._og(soup, \"novel:category\")\n        status = self._og(soup, \"novel:status\")\n        desc = self._og(soup, \"description\") or \"\"\n        desc = re.sub(r\"(?:emsp;|nbsp;)+\", \" \", desc)\n        chapters = self._toc(book_id)\n        vod_play_url = \"#\".join([f\"{t}${u}\" for t, u in chapters])\n        return {\n            \"list\": [{\n                \"vod_id\": book_id,\n                \"vod_name\": title or (\"书籍\" + book_id),\n                \"vod_pic\": pic,\n                \"vod_author\": author,\n                \"type_name\": category,\n                \"vod_content\": f\"作者：{author}  {category}  {status}\\n\\n{desc}\",\n                \"vod_play_from\": \"顶点小说\",\n                \"vod_play_url\": vod_play_url,\n            }]\n        }\n\n    # ---------------- 章节正文 ----------------\n    def playerContent(self, flag, id, vipFlags=None):\n        url = id if str(id).startswith(\"http\") else self._fix_url(id)\n        try:\n            m = re.search(r\"read_(\\d+)\", url)\n            base_cid = m.group(1) if m else None\n            title = \"\"\n            parts = []\n            current = url\n            for _ in range(20):\n                html = self._fetch(current)\n                if not html:\n                    break\n                soup = BeautifulSoup(html, \"html.parser\")\n                if not title:\n                    h3 = soup.select_one(\".word_read h3\")\n                    if h3:\n                        title = re.sub(r\"[（(]第\\d+页[)）]\\s*$\", \"\", h3.get_text(strip=True))\n                for b64 in re.findall(r\"qsbs\\.bb\\('([^']+)'\\)\", html):\n                    try:\n                        raw = base64.b64decode(b64).decode(\"utf-8\", \"ignore\")\n                    except Exception:\n                        continue\n                    cs = BeautifulSoup(raw, \"html.parser\")\n                    for tag in cs.find_all([\"script\", \"style\"]):\n                        tag.decompose()\n                    text = cs.get_text(\"\\n\", strip=True)\n                    if text:\n                        parts.append(text)\n                nxt = \"\"\n                for a in soup.select(\".word_read .read_btn a\"):\n                    if a.get_text(strip=True) == \"下一章\":\n                        nxt = a.get(\"href\", \"\")\n                        break\n                if not nxt:\n                    break\n                nxt = self._fix_url(nxt)\n                nm = re.search(r\"read_(\\d+)_(\\d+)\\.html\", nxt)\n                if not nm:\n                    break\n                if base_cid and nm.group(1) != base_cid:\n                    break\n                current = nxt\n            content = re.sub(r\"\\n\\s*\\n+\", \"\\n\\n\", \"\\n\".join(parts)).strip()\n            if not content:\n                content = \"未获取到章节内容\"\n            return self._novel_result(title or \"章节\", content)\n        except Exception as e:\n            print(f\"[顶点小说 playerContent] {e}\")\n            return self._novel_result(\"错误\", f\"发生异常: {e}\")\n\n    def _novel_result(self, title, content):\n        data = {\"title\": title, \"content\": content}\n        return {\n            \"parse\": 0,\n            \"playUrl\": \"\",\n            \"url\": \"novel://\" + json.dumps(data, ensure_ascii=False),\n            \"header\": \"\",\n        }\n\n    def isVideoFormat(self, url):\n        return False\n\n    def manualVideoCheck(self):\n        return False\n\n    def destroy(self):\n        try:\n            if self.session:\n                self.session.close()\n        except Exception:\n            pass\n\n    def localProxy(self, param):\n        return None\n",
    "七猫小说": "# -*- coding: utf-8 -*-\n# PickTV / PeekPro 小说源 - 七猫小说\n# 说明：七猫正文无轻量单章接口，采用\"整本 zip 下载 + 磁盘缓存\"方案。\n#   首次阅读某本书时下载整本（约几 MB~十几 MB），缓存到系统临时目录，\n#   之后各章节直接读缓存解密，速度快。\nimport re\nimport os\nimport json\nimport hashlib\nimport base64\nimport zipfile\nimport tempfile\nimport urllib.parse\n\nfrom base.spider import Spider\nimport requests\n\ntry:\n    from Crypto.Cipher import AES\nexcept Exception:\n    AES = None\n\n\nclass Spider(Spider):\n    def getName(self):\n        return \"七猫小说\"\n\n    def init(self, extend=\"\"):\n        self.sign_key = \"d3dGiJc651gSQ8w1\"\n        self.aes_key = bytes.fromhex(\"32343263636238323330643730396531\")\n        self.versions = [\n            \"73720\", \"73700\", \"73620\", \"73600\", \"73500\", \"73420\", \"73400\",\n            \"73328\", \"73325\", \"73320\", \"73300\", \"73220\", \"73200\", \"73100\",\n            \"73000\", \"72900\", \"72820\", \"72800\", \"70720\", \"62010\", \"62112\",\n        ]\n        self.api_bc = \"https://api-bc.wtzw.com\"\n        self.api_ks = \"https://api-ks.wtzw.com\"\n        self.rank_api = \"https://www.qimao.com/qimaoapi/api/rank/book-list\"\n        self.session = requests.Session()\n        # 不走系统代理：本地代理会干扰直连\n        self.session.trust_env = False\n        self.session.headers.update({\n            \"User-Agent\": \"Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36\",\n            \"Accept\": \"application/json, text/plain, */*\",\n        })\n        self.classes = [\n            (\"0|1\", \"男生·大热榜\"), (\"0|2\", \"男生·新书榜\"), (\"0|3\", \"男生·完结榜\"),\n            (\"1|1\", \"女生·大热榜\"), (\"1|2\", \"女生·新书榜\"), (\"1|3\", \"女生·完结榜\"),\n            (\"0|4\", \"收藏榜\"), (\"0|6\", \"更新榜\"),\n        ]\n        self._zip_dir = os.path.join(tempfile.gettempdir(), \"qimao_cache\")\n        try:\n            os.makedirs(self._zip_dir, exist_ok=True)\n        except Exception:\n            pass\n\n    # ---------------- 签名 / 请求 ----------------\n    def _md5(self, s):\n        return hashlib.md5(s.encode(\"utf-8\")).hexdigest()\n\n    def _sign(self, params):\n        return self._md5(\"\".join(k + \"=\" + str(params[k]) for k in sorted(params)) + self.sign_key)\n\n    def _stable_hash(self, s):\n        h = 0\n        for ch in s:\n            h = (h * 31 + ord(ch)) & 0xFFFFFFFF\n        if h >= 0x80000000:\n            h -= 0x100000000\n        return h\n\n    def _headers(self, book_id):\n        h = self._stable_hash(book_id) if book_id else 0\n        idx = abs(h) % len(self.versions)\n        hdrs = {\n            \"AUTHORIZATION\": \"\",\n            \"app-version\": self.versions[idx],\n            \"application-id\": \"com.****.reader\",\n            \"channel\": \"unknown\",\n            \"net-env\": \"1\",\n            \"platform\": \"android\",\n            \"qm-params\": \"\",\n            \"reg\": \"0\",\n        }\n        hdrs[\"sign\"] = self._sign(hdrs)\n        return hdrs\n\n    def _api(self, base, path, params, book_id):\n        params = dict(params)\n        params[\"sign\"] = self._sign(params)\n        headers = self._headers(book_id)\n        try:\n            resp = self.session.get(base + path, params=params, headers=headers, timeout=25)\n            return resp.json()\n        except Exception as e:\n            print(f\"[七猫小说 api error] {path} -> {e}\")\n            return {}\n\n    def _get(self, url, timeout=30, headers=None):\n        try:\n            return self.session.get(url, headers=headers or {}, timeout=timeout)\n        except Exception as e:\n            print(f\"[七猫小说 get error] {url} -> {e}\")\n            return None\n\n    # ---------------- 首页 / 分类 ----------------\n    def homeContent(self, filter=False):\n        return {\"class\": [{\"type_id\": tid, \"type_name\": name} for tid, name in self.classes]}\n\n    def _rank_books(self, is_girl, rank_type, page=1):\n        params = {\n            \"is_girl\": is_girl,\n            \"rank_type\": rank_type,\n            \"page\": str(page),\n            \"date_type\": \"1\" if rank_type in (\"4\", \"6\") else \"2\",\n        }\n        try:\n            r = self.session.get(self.rank_api, params=params, timeout=25)\n            data = r.json()\n        except Exception as e:\n            print(f\"[七猫小说 rank error] {e}\")\n            return []\n        out = []\n        for it in (data.get(\"data\") or {}).get(\"table_data\") or []:\n            bid = str(it.get(\"book_id\") or \"\")\n            if not bid:\n                continue\n            title = str(it.get(\"title\") or \"\").strip()\n            author = str(it.get(\"author\") or \"\").strip()\n            cat = \" \".join(x for x in [\n                str(it.get(\"category1_name\") or \"\"),\n                str(it.get(\"category2_name\") or \"\"),\n            ] if x)\n            status = \"完结\" if str(it.get(\"is_over\")) == \"1\" else \"连载\"\n            hot = str(it.get(\"number\") or \"\") + str(it.get(\"unit\") or \"\")\n            remarks = \" \".join(x for x in [cat, status, hot] if x)\n            out.append({\n                \"vod_id\": bid,\n                \"vod_name\": title or (\"书籍\" + bid),\n                \"vod_pic\": str(it.get(\"image_link\") or \"\"),\n                \"vod_remarks\": remarks,\n                \"vod_content\": str(it.get(\"intro\") or \"\"),\n                \"vod_author\": author,\n            })\n        return out\n\n    def homeVideoContent(self):\n        return {\"list\": self._rank_books(\"0\", \"1\", 1)[:40]}\n\n    def categoryContent(self, tid, pg, filter=False, extend=\"\"):\n        try:\n            pg = int(pg) if pg else 1\n        except ValueError:\n            pg = 1\n        m = re.match(r\"^(\\d)\\|(\\d+)$\", str(tid))\n        if not m:\n            return {\"list\": []}\n        books = self._rank_books(m.group(1), m.group(2), pg)\n        pagecount = pg + 1 if books else pg\n        return {\n            \"list\": books,\n            \"page\": pg,\n            \"pagecount\": pagecount,\n            \"limit\": len(books) or 20,\n            \"total\": (len(books) or 20) * pagecount,\n        }\n\n    # ---------------- 搜索 ----------------\n    def searchContent(self, key, quick=False, pg=\"1\"):\n        if int(pg or 1) > 1:\n            return {\"list\": [], \"page\": 1, \"pagecount\": 1, \"limit\": 20, \"total\": 0}\n        d = self._api(self.api_bc, \"/search/v1/words\", {\n            \"extend\": \"\", \"tab\": \"0\", \"gender\": \"0\", \"refresh_state\": \"8\", \"page\": \"1\",\n            \"wd\": key, \"is_short_story_user\": \"0\",\n        }, \"00000000\")\n        out = []\n        for it in (d.get(\"data\") or {}).get(\"books\") or []:\n            bid = str(it.get(\"id\") or \"\")\n            if not bid:\n                continue\n            title = re.sub(r\"<[^>]+>\", \"\", str(it.get(\"title\") or \"\")).strip()\n            author = re.sub(r\"<[^>]+>\", \"\", str(it.get(\"author\") or \"\")).strip()\n            sub = re.sub(r\"<[^>]+>\", \"\", str(it.get(\"sub_title\") or \"\")).strip()\n            out.append({\n                \"vod_id\": bid,\n                \"vod_name\": title or (\"书籍\" + bid),\n                \"vod_pic\": str(it.get(\"image_link\") or \"\"),\n                \"vod_remarks\": \" \".join(x for x in [author, sub] if x),\n            })\n        return {\"list\": out, \"page\": 1, \"pagecount\": 1, \"limit\": 20, \"total\": len(out)}\n\n    # ---------------- 详情 ----------------\n    def detailContent(self, ids):\n        ids = ids if isinstance(ids, list) else [ids]\n        m = re.search(r\"(\\d+)\", str(ids[0]))\n        if not m:\n            return {}\n        book_id = m.group(1)\n        d = self._api(self.api_bc, \"/api/v4/book/detail\", {\n            \"id\": book_id, \"imei_ip\": \"2937357107\", \"teeny_mode\": \"0\",\n        }, book_id)\n        book = (d.get(\"data\") or {}).get(\"book\") or {}\n        title = str(book.get(\"title\") or \"书籍\").strip()\n        author = str(book.get(\"author\") or \"\").strip()\n        pic = str(book.get(\"image_link\") or \"\")\n        intro = str(book.get(\"intro\") or \"\").strip()\n        cat = \" \".join(x for x in [\n            str(book.get(\"category1_name\") or \"\"),\n            str(book.get(\"category2_name\") or \"\"),\n        ] if x)\n        tags = []\n        for t in (book.get(\"book_tag_list\") or []):\n            tname = str(t.get(\"title\") or \"\").strip() if isinstance(t, dict) else \"\"\n            if tname:\n                tags.append(tname)\n        chapters = self._chapters(book_id)\n        if not chapters:\n            return {}\n        vod_play_url = \"#\".join([\n            f\"{t}$qimao://{book_id}/{cid}/{urllib.parse.quote(t)}\" for cid, t in chapters\n        ])\n        desc = \"\\n\\n\".join(x for x in [\n            (\"作者：\" + author + \"  \" + cat).strip(),\n            intro,\n            (\"标签：\" + \"、\".join(tags)) if tags else \"\",\n        ] if x)\n        return {\n            \"list\": [{\n                \"vod_id\": book_id,\n                \"vod_name\": title,\n                \"vod_pic\": pic,\n                \"vod_author\": author,\n                \"type_name\": cat,\n                \"vod_content\": desc,\n                \"vod_play_from\": \"七猫小说\",\n                \"vod_play_url\": vod_play_url,\n            }]\n        }\n\n    def _chapters(self, book_id):\n        d = self._api(self.api_ks, \"/api/v1/chapter/chapter-list\", {\n            \"chapter_ver\": \"0\", \"id\": book_id,\n        }, book_id)\n        raw = (d.get(\"data\") or {}).get(\"chapter_lists\") or []\n        chs = []\n        for it in raw:\n            cid = str(it.get(\"id\") or \"\")\n            t = str(it.get(\"title\") or \"\").strip()\n            if cid and t:\n                chs.append((cid, t))\n        # 按章节 ID 升序\n        try:\n            chs.sort(key=lambda x: int(x[0]))\n        except Exception:\n            pass\n        return chs\n\n    # ---------------- 章节正文（整本 zip 缓存） ----------------\n    def _zip_path(self, book_id):\n        return os.path.join(self._zip_dir, \"qimao_%s.zip\" % book_id)\n\n    def _download_zip(self, book_id):\n        path = self._zip_path(book_id)\n        if os.path.exists(path) and os.path.getsize(path) > 1024:\n            return path\n        d = self._api(self.api_bc, \"/api/v1/book/download\", {\n            \"id\": book_id, \"source\": \"1\", \"type\": \"2\", \"is_vip\": \"1\",\n        }, book_id)\n        link = ((d.get(\"data\") or {}).get(\"link\") or \"\")\n        if not link:\n            print(f\"[七猫小说] 未获取到下载链接 book={book_id}\")\n            return None\n        resp = self._get(link, timeout=180, headers=self._headers(\"\"))\n        if resp is None or resp.status_code != 200 or not resp.content:\n            print(f\"[七猫小说] 整本下载失败 book={book_id}\")\n            return None\n        tmp = path + \".tmp\"\n        try:\n            with open(tmp, \"wb\") as f:\n                f.write(resp.content)\n            os.replace(tmp, path)\n        except Exception as e:\n            print(f\"[七猫小说] 写入缓存失败 {e}\")\n        return path\n\n    def _decrypt_chapter(self, data):\n        try:\n            text = data.decode(\"utf-8\", \"ignore\")\n        except Exception:\n            text = \"\"\n        if AES is None or not text.strip():\n            return text\n        try:\n            raw = base64.b64decode(text)\n            if len(raw) < 16:\n                return text\n            iv, ct = raw[:16], raw[16:]\n            if len(ct) % 16 != 0:\n                return text\n            plain = AES.new(self.aes_key, AES.MODE_CBC, iv).decrypt(ct)\n            pad = plain[-1]\n            if 1 <= pad <= 16 and pad <= len(plain):\n                plain = plain[:-pad]\n            return plain.decode(\"utf-8\", \"ignore\")\n        except Exception as e:\n            print(f\"[七猫小说] 解密失败 {e}\")\n            return text\n\n    def _read_chapter(self, book_id, chapter_id):\n        path = self._download_zip(book_id)\n        if not path:\n            return None\n        try:\n            with zipfile.ZipFile(path) as z:\n                target = None\n                for n in z.namelist():\n                    if n == chapter_id or n == chapter_id + \".txt\" or n.rstrip(\".txt\") == chapter_id:\n                        target = n\n                        break\n                if target is None:\n                    return None\n                data = z.read(target)\n        except Exception as e:\n            print(f\"[七猫小说] 读取缓存失败 {e}\")\n            return None\n        return self._decrypt_chapter(data)\n\n    def playerContent(self, flag, id, vipFlags=None):\n        sid = str(id)\n        # 兼容两种格式：qimao://book/cid/标题 与 book:cid\n        if \"%\" in sid:\n            try:\n                sid = urllib.parse.unquote(sid)\n            except Exception:\n                pass\n        title = \"\"\n        m = re.match(r\"^qimao://(\\d+)/(\\d+)/(.*)$\", sid)\n        if m:\n            book_id, chapter_id, title = m.group(1), m.group(2), m.group(3)\n            if \"%\" in title:\n                try:\n                    title = urllib.parse.unquote(title)\n                except Exception:\n                    pass\n        else:\n            m2 = re.match(r\"^(\\d+):(\\d+)$\", sid)\n            if m2:\n                book_id, chapter_id = m2.group(1), m2.group(2)\n            else:\n                book_id, chapter_id = sid, \"\"\n        if not chapter_id:\n            return self._novel_result(\"章节\", \"未获取到章节内容\")\n        content = self._read_chapter(book_id, chapter_id)\n        if not content:\n            content = \"未获取到章节内容（可能需会员或下载失败）\"\n        return self._novel_result(title or \"章节\", content)\n\n    def _novel_result(self, title, content):\n        data = {\"title\": title, \"content\": content}\n        return {\n            \"parse\": 0,\n            \"playUrl\": \"\",\n            \"url\": \"novel://\" + json.dumps(data, ensure_ascii=False),\n            \"header\": \"\",\n        }\n\n    def isVideoFormat(self, url):\n        return False\n\n    def manualVideoCheck(self):\n        return False\n\n    def destroy(self):\n        try:\n            if self.session:\n                self.session.close()\n        except Exception:\n            pass\n\n    def localProxy(self, param):\n        return None\n",
}
